// Where image files live. Default: the D1 database itself (table media_blobs), so the Community Hub needs nothing
// besides the website's Worker and its D1 database: no R2 bucket, no billing. An R2 bucket (binding MEDIA) or KV
// namespace (binding MEDIA_KV) is used instead if one is ever bound. Keys are generated by the server only.

import type { Env } from "./env";

const KEY = /^(img|thumb)\/[0-9a-f]{32}\.(png|jpg)$/;

/** D1 stores at most 2 MB per row; images are kept below this (see images.ts). */
export const D1_MAX_BLOB = 1_800_000;

export interface MediaStore {
  kind: "r2" | "kv" | "d1";
  put(key: string, data: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<{ body: ReadableStream | ArrayBuffer | Uint8Array; contentType: string } | null>;
  delete(key: string): Promise<void>;
}

export function checkKey(key: string): string {
  if (!KEY.test(key)) throw new Error("Invalid object key.");
  return key;
}

export function mediaStore(env: Env): MediaStore | null {
  if (env.MEDIA) {
    const b = env.MEDIA;
    return {
      kind: "r2",
      async put(key, data, contentType) { await b.put(checkKey(key), data, { httpMetadata: { contentType } }); },
      async get(key) {
        const o = await b.get(checkKey(key));
        return o ? { body: o.body, contentType: o.httpMetadata?.contentType ?? "application/octet-stream" } : null;
      },
      async delete(key) { await b.delete(checkKey(key)); },
    };
  }
  if (env.MEDIA_KV) {
    const kv = env.MEDIA_KV;
    return {
      kind: "kv",
      async put(key, data, contentType) { await kv.put(checkKey(key), data, { metadata: { contentType } }); },
      async get(key) {
        const r = await kv.getWithMetadata<{ contentType: string }>(checkKey(key), "arrayBuffer");
        return r.value ? { body: r.value, contentType: r.metadata?.contentType ?? "application/octet-stream" } : null;
      },
      async delete(key) { await kv.delete(checkKey(key)); },
    };
  }
  if (env.DB) {
    const db = env.DB;
    return {
      kind: "d1",
      async put(key, data, contentType) {
        if (data.length > D1_MAX_BLOB) throw new Error("Image too large for database storage.");
        await db.prepare("INSERT OR REPLACE INTO media_blobs (key, content_type, data, bytes, created_utc) VALUES (?1, ?2, ?3, ?4, ?5)")
          .bind(checkKey(key), contentType, data, data.length, new Date().toISOString()).run();
      },
      async get(key) {
        const r = await db.prepare("SELECT content_type, data FROM media_blobs WHERE key = ?1").bind(checkKey(key)).first<{ content_type: string; data: ArrayBuffer | number[] }>();
        if (!r) return null;
        const body = r.data instanceof ArrayBuffer ? new Uint8Array(r.data) : Uint8Array.from(r.data);
        return { body, contentType: r.content_type };
      },
      async delete(key) { await db.prepare("DELETE FROM media_blobs WHERE key = ?1").bind(checkKey(key)).run(); },
    };
  }
  return null;
}
